const IMAGES = [
  { id: 1, name: "mountain-sunrise.jpg",  size: "3.2 MB · JPEG", src: "https://picsum.photos/seed/mtn/400/300"   },
  { id: 2, name: "city-skyline.png",      size: "5.1 MB · PNG",  src: "https://picsum.photos/seed/city/400/300"  },
  { id: 3, name: "forest-trail.jpg",      size: "2.8 MB · JPEG", src: "https://picsum.photos/seed/fst/400/300"   },
