    /* Remove card from DOM */
    const card = document.querySelector(`.image-card[data-id="${activeImageId}"]`);
    if (card) card.remove();

    /* Update subtitle count */
    const remaining = document.querySelectorAll(".image-card").length;
    document.querySelector(".page-subtitle").textContent = `${remaining} images`;

    closeModal();
  }

  /* ── Event wiring ──────────────────────────── */

  /* Open: delegate to all .trigger buttons */
  document.addEventListener("click", (e) => {
    const trigger = e.target.closest(".trigger");
    if (!trigger) return;
    const { imageId, imageName, imageSrc } = trigger.dataset;
    openModal(imageId, imageName, imageSrc);
  });

  cancelBtn.addEventListener("click", closeModal);
  confirmBtn.addEventListener("click", confirmDelete);

  /* Close on backdrop click */
  overlay.addEventListener("click", (e) => {
    if (e.target === overlay) closeModal();
  });

  /* Close on Escape */
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && overlay.classList.contains("is-open")) {
      closeModal();
    }
  });

  /* Focus trap inside dialog */
  overlay.addEventListener("keydown", (e) => {
    if (e.key !== "Tab" || !overlay.classList.contains("is-open")) return;
    const focusable = Array.from(
      overlay.querySelectorAll('button, [href], input, [tabindex]:not([tabindex="-1"])')
    ).filter(el => !el.disabled);
    if (!focusable.length) return;
    const first = focusable[0];
    const last  = focusable[focusable.length - 1];
    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  });
}

/* Boot */
document.addEventListener("DOMContentLoaded", App);
