  { id: 5, name: "desert-dunes.jpg",      size: "3.9 MB · JPEG", src: "https://picsum.photos/seed/drt/400/300"   },
  { id: 6, name: "autumn-leaves.jpg",     size: "2.2 MB · JPEG", src: "https://picsum.photos/seed/aut/400/300"   },
];

function App() {
  const root = document.getElementById("app");

  root.innerHTML = `
    <header class="page-header" role="banner">
      <span class="page-header__logo" aria-label="Luminary home">Luminary</span>
      <nav class="page-header__nav" aria-label="Main navigation">
        <a href="#">Dashboard</a>
        <a href="#" class="active" aria-current="page">Library</a>
        <a href="#">Projects</a>
        <a href="#">Settings</a>
